const MT_NOTES = [10, 20, 50, 100, 200, 500];
const MT_COINS = [1, 2, 5, 10, 20];
const MT_BLUE = CONTENT.hundred;
const MT_BLUE_INK = shade(CONTENT.hundred, 0.25);
const MT_SKY = "#56B4E9";
const MT_SKY_INK = shade("#56B4E9", 0.45);
const MT_NOTE = tint(CONTENT.hundred, 0.8);
const MT_NOTE_EDGE = tint(CONTENT.hundred, 0.25);
const MT_STEEL = "#CBD2D9";
const MT_STEEL_EDGE = "#7A8793";
const MT_LINE = CONTENT.line;
let mtRupee = "Rs ";
const mtSetLang = (lang) => {
  mtRupee = lang && lang !== "en" ? "₹" : "Rs ";
};
const mtRs = (x) => mtRupee + indian(x);
const mtAmount = (gs) => gs.reduce((a, g) => a + g.v * g.n, 0);
const mtHeap = (s) => s.split(" ").map((t) => ({ k: t[0] === "n" ? "note" : "coin", v: Number(t.slice(1)) }));
const MT_SHOWN = {
  note: "The note",
  coins: "The coins",
  coin: "The coin",
  same: "The same",
  short: "Short",
  exact: "Exactly enough",
  more: "More than enough",
  first: "First child",
  second: "Second child",
  neither: "Neither"
};
const mtShown = (v) => {
  const s = String(v === null || v === void 0 ? "" : v);
  if (MT_SHOWN[s]) return MT_SHOWN[s];
  return /^[1-9]\d*$/.test(s) ? mtRupee + indian(Number(s)) : /^\d+$/.test(s) ? mtRupee + s : s;
};
const mtFormat = (v, _j, o) => {
  mtSetLang(o && o.lang);
  return mtShown(v);
};
